// ---- deep-linkable URL hash routing (T35) ------------------------------
export const PERIOD_VALUES = new Set(['all_day', 'am_rush', 'midday', 'pm_rush', 'late_night']);

/** Read a deep-link hash (`#explore&route=36&period=am_rush`) into parts. */
export function parseRouteHash(hash: string): {
  view?: string;
  route?: string;
  period?: string;
} {
  const raw = hash.replace(/^#/, '').trim();
  if (!raw) return {};
  const out: { view?: string; route?: string; period?: string } = {};
  for (const part of raw.split('&')) {
    const eq = part.indexOf('=');
    const key = eq === -1 ? part : part.slice(0, eq);
    const value = eq === -1 ? '' : part.slice(eq + 1);
    try {
      if (key === 'route' && value) out.route = decodeURIComponent(value);
      else if (key === 'period' && value) out.period = decodeURIComponent(value);
      else if (key && !out.view) out.view = key; // first bare token = view key
    } catch {
      // malformed percent-encoding -> ignore the bad token
    }
  }
  return out;
}

/** Build the deep-link hash reflecting the current routable state.
 * Only `view` + `route=` are written back during navigation; `period=` is
 * parsed on mount and on manually-entered hashes but kept out of the
 * live write-back value so it behaves as sticky global filter state and
 * never re-asserts itself over a Back/forward navigation (which would push
 * a phantom history entry and fight the Back button). */
export function buildRouteHash(view: string, highlightedRoute: string | null): string {
  let h = `#${view}`;
  if (highlightedRoute) h += `&route=${encodeURIComponent(highlightedRoute)}`;
  return h;
}

