/**
 * Static-mode API patch.
 *
 * When the app runs on GitHub Pages (or any host without a live backend),
 * this module intercepts `fetch('/api/...')` calls and redirects them to
 * `/api-snapshot/<endpoint>.json` files that were pre-generated by the
 * snapshot script.
 *
 * It also emulates the async optimizer job flow (POST to start, GET to poll)
 * by replaying the pre-computed default result (optimize-default.json), so
 * the Fix transfers tab shows real charts without a backend.
 *
 * Import this module once at app startup — it's a no-op in dev mode.
 */

/** Base path for snapshot files. Vite injects BASE_URL — '/' in dev,
 *  '/miway-transit-optimizer/' on Pages builds — so this follows the build
 *  instead of hardcoding one repo's Pages path (works from any host path). */
const SNAPSHOT_BASE = (import.meta.env.BASE_URL ?? '/').replace(/\/$/, '') + '/api-snapshot';

/**
 * Live-API layer (2026-09-20): the Pages demo prefers the LIVE read-only API
 * (evening fallback on the laptop, exposed via a Cloudflare quick tunnel)
 * and falls back to frozen snapshots whenever the live API is unreachable —
 * e.g. the laptop is asleep outside the 15:00–22:00 window.
 *
 * Quick-tunnel URLs are ephemeral: they change when the fallback restarts.
 * Update LIVE_API_URLS when the tunnel URL changes (candidate list — first
 * one that answers /api/health wins). The probe result is cached in
 * sessionStorage with a TTL so a laptop waking mid-session is re-detected
 * without re-probing on every fetch.
 */
const LIVE_API_URLS: string[] = [
  'https://another-echo-fellowship-october.trycloudflare.com',
];
const LIVE_PROBE_TIMEOUT_MS = 4000;
const LIVE_DECISION_TTL_MS = 10 * 60 * 1000;
const LIVE_CACHE_KEY = 'miway-live-api';

interface LiveDecision { base: string | null; ts: number }

function readLiveCache(): LiveDecision | null {
  try {
    const raw = sessionStorage.getItem(LIVE_CACHE_KEY);
    if (!raw) return null;
    const d = JSON.parse(raw) as LiveDecision;
    if (Date.now() - d.ts > LIVE_DECISION_TTL_MS) return null;
    return d;
  } catch { return null; }
}

function writeLiveCache(d: LiveDecision): void {
  try { sessionStorage.setItem(LIVE_CACHE_KEY, JSON.stringify(d)); } catch { /* private mode */ }
}

/** Probe the candidate live APIs once per TTL. Resolves to the winning base
 *  URL, or null when every candidate is unreachable (snapshot mode). */
async function resolveLiveBase(): Promise<string | null> {
  const cached = readLiveCache();
  if (cached) return cached.base;
  for (const base of LIVE_API_URLS) {
    try {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), LIVE_PROBE_TIMEOUT_MS);
      const resp = await fetch(`${base}/api/health`, { signal: ctrl.signal });
      clearTimeout(t);
      if (resp.ok) { writeLiveCache({ base, ts: Date.now() }); return base; }
    } catch { /* next candidate */ }
  }
  writeLiveCache({ base: null, ts: Date.now() });
  return null;
}

/** Fake job id used when replaying the pre-computed optimizer result. */
const FAKE_JOB_ID = 'snapshot-default';

/** Map of /api paths → snapshot filenames. */
const ROUTE_MAP: Record<string, string> = {
  '/api/health':                       'health',
  '/api/routes/circuity':             'routes-circuity',
  '/api/routes/circuity/summary':     'routes-circuity-summary',
  '/api/routes/circuity/best-pilot':  'routes-circuity-best-pilot',
  '/api/routes/corridor-gaps':        'routes-corridor-gaps',
  '/api/transfer/nodes':              'transfer-nodes',
  '/api/optimize/transfers/top-missed': 'optimize-top-missed',
  '/api/diagnostics/transfer-blindspots': 'diagnostics-blindspots',
  '/api/equity/report':               'equity-report',
  '/api/equity/ward-demographics':    'equity-ward-demographics',
  '/api/report/executive-brief':      'report-executive-brief',
  '/api/service-quality':             'service-quality',
  '/api/coverage':                    'coverage',
  '/api/measured/reliability':        'measured-reliability',
  '/api/measured/schedule-padding':   'measured-schedule-padding',
  '/api/measured':                    'measured',
  '/api/operations/trends':           'operations-trends',
  '/api/changeover':                  'changeover',
  '/api/swarm-scoreboard':            'swarm-scoreboard',
  '/api/diagnostics/data-vintage':    'diagnostics-data-vintage',
  '/api/peers':                       'peers',
  '/api/public/early-departures':     'public-early-departures',
  '/api/forecast/scoreboard':         'forecast-scoreboard',
};

// NOTE: static/demo mode activates on GitHub Pages hosts, any /demo/ path,
// or explicit opt-in (?static). Snapshots are public data — activation by
// URL is a feature (resume readers get the demo), not a leak.
export function isDemoMode(): boolean {
  if (typeof window === 'undefined') return false;
  const h = window.location.hostname;
  return h.endsWith('.github.io') ||
    window.location.pathname.includes('/demo/') ||
    window.location.search.includes('static');
}

/** True when this build is serving frozen snapshots instead of a live
 *  backend — App renders a demo banner when set. Set at startup by
 *  patchFetchForStatic() on static hosts. */
export let DEMO_MODE = false;

function isStaticHost(): boolean {
  return isDemoMode();
}

function jsonResponse(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

function nowIso(): string {
  return new Date().toISOString();
}

/** Call once at app startup. No-op if not on a static host. */
export function patchFetchForStatic(): void {
  if (!isStaticHost()) return;

  DEMO_MODE = true;

  const origFetch = window.fetch.bind(window);

  window.fetch = (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
    const method = (
      init?.method ??
      (typeof input === 'object' && input !== null && 'method' in input ? input.method : 'GET') ??
      'GET'
    ).toUpperCase();

    // Only intercept /api/ routes
    if (!url.startsWith('/api/')) {
      return origFetch(input, init);
    }

    const path = url.split('?')[0];

    // POST /api/optimize/transfers/async — "start" the pre-computed job.
    // It reports running once, then the poll below immediately completes it,
    // so the panel's normal UI flow works unchanged.
    if (method === 'POST' && path === '/api/optimize/transfers/async') {
      console.log('[static] optimizer → replaying pre-computed snapshot job');
      return Promise.resolve(
        jsonResponse({ job_id: FAKE_JOB_ID, status: 'running', created_at: nowIso() })
      );
    }

    // Any other POST (travel compare, equity compute, …) has no snapshot —
    // fall through to the network so the panel shows its backend error UI.
    if (method !== 'GET') {
      return origFetch(input, init);
    }

    // GET /api/... — live API first, snapshot fallback. resolveLiveBase is
    // one cached probe per TTL; per-request overhead when live is a no-op
    // prefix join, when dead it is skipped entirely.
    const snapshotName = ROUTE_MAP[path];
    if (snapshotName) {
      return resolveLiveBase().then((base) => {
        const liveUrl = base !== null
          ? `${base}${path}${url.includes('?') ? url.slice(url.indexOf('?')) : ''}`
          : null;
        const target = liveUrl ?? `${SNAPSHOT_BASE}/${snapshotName}.json`;
        return origFetch(target, init).then((resp) => {
          if (resp.ok || liveUrl === null) return resp;
          // Live answered but errored (or died mid-TTL) — serve the frozen
          // snapshot and invalidate the cached live decision so the next
          // request re-probes instead of trusting a stale "live" verdict.
          writeLiveCache({ base: null, ts: Date.now() });
          console.warn(`[static] live ${path} -> ${resp.status}; falling back to snapshot`);
          return origFetch(`${SNAPSHOT_BASE}/${snapshotName}.json`, init);
        });
      });
    }

    // GET /api/optimize/transfers/async/{job_id} — complete the replayed job
    // with the pre-computed default result.
    if (path.startsWith('/api/optimize/transfers/async/')) {
      const snapshotUrl = `${SNAPSHOT_BASE}/optimize-default.json`;
      console.log(`[static] optimizer job → ${snapshotUrl}`);
      return origFetch(snapshotUrl, init).then((resp) => {
        if (!resp.ok) return resp;
        return resp.json().then((result) =>
          jsonResponse({
            job_id: FAKE_JOB_ID,
            status: 'completed',
            created_at: nowIso(),
            started_at: nowIso(),
            completed_at: nowIso(),
            result,
            error: null,
            progress: 100,
          })
        );
      });
    }

    // Unmapped GET paths (no snapshot): pass through so panels show their
    // backend error UI.
    return origFetch(input, init);
  };
  console.log('[static] Fetch patched for GitHub Pages mode');
}
