import { useCallback, useEffect, useState, lazy, Suspense } from 'react';
import { AlertTriangle } from 'lucide-react';

import GettingStarted from './components/GettingStarted';
import HomePanel from './components/HomePanel';
import LoadingBar from './components/LoadingBar';
import AppHeader from './components/layout/AppHeader';
import DemoBanner from './components/DemoBanner';
import DemoIntroCard from './components/DemoIntroCard';
import AppSidebar from './components/layout/AppSidebar';
import PanelErrorBoundary from './components/PanelErrorBoundary';

// Every panel except Home is lazy: the initial bundle ships only the shell
// + Home, and each view's chunk loads on first navigation (route-level code
// splitting). HomePanel stays eager for first paint.
const EquityPanel = lazy(() => import('./components/EquityPanel'));
const ExecutiveBriefPanel = lazy(() => import('./components/ExecutiveBriefPanel'));
const ServiceQualityPanel = lazy(() => import('./components/ServiceQualityPanel'));
const CoveragePanel = lazy(() => import('./components/CoveragePanel'));
const ChangeoverPanel = lazy(() => import('./components/ChangeoverPanel'));
const EarlyDeparturesPanel = lazy(() => import('./components/EarlyDeparturesPanel'));
const SlownessCard = lazy(() => import('./components/SlownessCard'));
const ForecastScoreboardPanel = lazy(() => import('./components/ForecastScoreboardPanel'));
const ReliabilityPanel = lazy(() => import('./components/ReliabilityPanel'));
const TripCheckPanel = lazy(() => import('./components/TripCheckPanel'));
const PeersPanel = lazy(() => import('./components/PeersPanel'));
const MeasuredVsModeledPanel = lazy(() => import('./components/MeasuredVsModeledPanel'));
const DiagnosticsPanel = lazy(() => import('./components/DiagnosticsPanel'));
const MapWorkspace = lazy(() => import('./components/layout/MapWorkspace'));
import { loadAppState, saveAppState } from './lib/persist';
import { useIsMobile } from './lib/useIsMobile';
import { useOptimizerSettings } from './hooks/useOptimizerSettings';
import { useOptimizeJob } from './hooks/useOptimizeJob';
import { useStaticData } from './hooks/useStaticData';
import { useViewRouting } from './hooks/useViewRouting';
import { useMapLayers } from './hooks/useMapLayers';
import { useTravelPlanner } from './hooks/useTravelPlanner';
import type { View } from './lib/viewConfig';


/** Fallback-card labels for the per-panel error boundary. */
const VIEW_LABELS: Partial<Record<View, string>> = {
  home: 'Home',
  diagnostics: 'Diagnostics',
  equity: 'Equity',
  brief: 'Councillor brief',
  servicequality: 'Service quality',
  coverage: 'Collection coverage',
  changeover: 'Changeover impact',
  measured: 'Measured vs modeled',
  reliability: 'Transfer reliability',
  tripcheck: 'Will I make it?',
  earlydepartures: 'Early departures',
  scoreboard: 'Forecast scoreboard',
  slowness: 'Why so slow?',
  peers: 'Peers & open data',
  optimize: 'Fix transfers',
  routes: 'Network map',
  explore: 'Winding routes',
  trunkfeeder: 'Trunk & feeder',
  travel: 'Plan a trip',
};

/** Shared Suspense fallback for the lazy panels: a quiet centered spinner
 * (first navigation fetches the chunk; subsequent visits are instant). */
function PanelFallback() {
  return (
    <div className="flex flex-1 items-center justify-center p-8 text-text-muted" role="status" aria-label="Loading panel">
      <div className="h-6 w-6 animate-spin rounded-full border-2 border-border border-t-accent" />
    </div>
  );
}

/**
 * Composition root. Owns only cross-cutting concerns (persistence, global
 * error, retry); every domain concern has a single owning hook:
 *
 *   useViewRouting      URL-routable state (view, period, highlightedRoute)
 *   useOptimizerSettings slider values + buildRequest payload
 *   useStaticData       backend static data, per-period cache, load progress
 *   useOptimizeJob      optimization run lifecycle + result
 *   useMapLayers        map layer toggles, engine, corridor seam
 *   useTravelPlanner    travel picks, itineraries, derived map overlay
 *
 * Data flows one way: hooks -> props -> presentation components.
 */
export default function App() {
  // Hydrate controls/results from localStorage so a refresh doesn't lose the
  // last run (best-effort; absent on first visit or in private mode).
  const [saved] = useState(() => loadAppState());
  const isMobile = useIsMobile();
  const [drawerOpen, setDrawerOpen] = useState(false);
  // AppHeader's hamburger broadcasts a DOM event (header owns its own button
  // state); App owns the drawer. Bridge the two here.
  useEffect(() => {
    if (!isMobile) return;
    const toggle = () => setDrawerOpen((v) => !v);
    window.addEventListener('miway:toggle-nav', toggle);
    return () => window.removeEventListener('miway:toggle-nav', toggle);
  }, [isMobile]);

  // ---- URL-routable state ------------------------------------------------
  const {
    view, setView,
    period, setPeriod,
    highlightedRoute, setHighlightedRoute,
    showHelp, setShowHelp, dismissHelp,
    collapsed, toggleGroup,
  } = useViewRouting({
    savedPeriod: saved?.period ?? null,
    savedHighlightedRoute: saved?.highlightedRoute ?? null,
  });

  // ---- domain hooks --------------------------------------------------------
  const settings = useOptimizerSettings(saved);

  const {
    health, dataFreshness, feedVintage, circuity, flaggedRoutes, circuityThreshold,
    nodes, setNodes, periods, error, setError,
    loadProgress, onHomeLoaded, loadStatic,
  } = useStaticData(period, view, saved?.result?.nodes ?? []);

  const buildRequest = useCallback(
    () => settings.buildRequest(period, periods),
    [settings, period, periods],
  );

  // True when the most recent optimization attempt failed, so the global
  // Retry button can re-run the job instead of only refetching static data.
  const [jobFailed, setJobFailed] = useState(false);

  const {
    running, result, resultPeriod, resultServiceDay,
    runOptimization, exportGtfs, downloadPlannerReport,
  } = useOptimizeJob({
    buildRequest,
    period,
    serviceDay: settings.serviceDay,
    setNodes,
    setHighlightedRoute,
    setError,
    onJobSettled: setJobFailed,
  });

  const layers = useMapLayers(view);
  const travel = useTravelPlanner(view);

  // ---- cross-cutting concerns ---------------------------------------------
  const [retryTick, setRetryTick] = useState(0);

  // Persist controls + the last run so a refresh restores them.
  useEffect(() => {
    saveAppState({
      maxShift: settings.maxShift,
      bufferMinutes: settings.bufferMinutes,
      highFreqCutoff: settings.highFreqCutoff,
      tMax: settings.tMax,
      serviceDay: settings.serviceDay,
      volumeMode: settings.volumeMode,
      period,
      result,
      resultPeriod,
      resultServiceDay,
      highlightedRoute,
      minLayoverMinutes: settings.minLayoverMinutes,
      timeLimitSeconds: settings.timeLimitSeconds,
      maxConnections: settings.maxConnections,
    });
  }, [
    settings, period, result, resultPeriod, resultServiceDay, highlightedRoute,
  ]);

  const retry = useCallback(() => {
    setRetryTick((t) => t + 1); // also refresh the Home cards
    loadStatic();
    // The error may have come from the optimization job rather than the
    // static load — refetching static data alone would leave the user's
    // actual intent ("re-run the optimization") silently unmet.
    if (jobFailed) runOptimization();
  }, [loadStatic, jobFailed, runOptimization]);

  const periodLabel = periods?.[period]?.label ?? period;
  const resultPeriodLabel = resultPeriod
    ? periods?.[resultPeriod]?.label ?? resultPeriod
    : null;

  // ---- render --------------------------------------------------------------
  return (
    <div className="flex h-screen flex-col bg-bg text-text-primary">
      <DemoBanner />
      <AppHeader
        view={view}
        health={health}
        feedVintage={feedVintage}
        dataFreshness={dataFreshness}
        serviceDay={settings.serviceDay}
        setServiceDay={settings.setServiceDay}
        period={period}
        setPeriod={setPeriod}
        periods={periods}
        onShowHelp={() => setShowHelp(true)}
      />

      {loadProgress && <LoadingBar {...loadProgress} />}

      {showHelp && <GettingStarted onDismiss={dismissHelp} />}

      {error && (
        <div className="flex items-center gap-2 border-b border-danger/40 bg-danger/10 px-4 py-2 text-xs text-danger">
          <AlertTriangle className="h-4 w-4" />
          <span>Backend error: {error}</span>
          <button onClick={retry} className="ml-auto underline">
            Retry
          </button>
        </div>
      )}

      <div className="relative flex flex-1 overflow-hidden">
        {isMobile && drawerOpen && (
          <div
            className="absolute inset-0 z-30 bg-black/50"
            onClick={() => setDrawerOpen(false)}
            aria-label="Close navigation"
          />
        )}
        <div
          className={
            isMobile
              ? `absolute inset-y-0 left-0 z-40 transition-transform duration-200 ${drawerOpen ? 'translate-x-0' : '-translate-x-full'}`
              : 'relative'
          }
        >
          <AppSidebar
            view={view}
            setView={(v) => {
              setView(v);
              setDrawerOpen(false); // close drawer after picking a view on mobile
            }}
            collapsed={collapsed}
            toggleGroup={toggleGroup}
          />
        </div>

        <main className="flex flex-1 flex-col gap-3 overflow-hidden p-3">
          <PanelErrorBoundary label={VIEW_LABELS[view] ?? view}>
          {view === 'home' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-5xl p-2">
                <DemoIntroCard />
                <HomePanel
                  period={period}
                  serviceDay={settings.serviceDay}
                  maxShift={settings.maxShift}
                  refreshToken={retryTick}
                  onLoaded={onHomeLoaded}
                  onOpenTransfers={() => setView('optimize')}
                  onOpenTrunkFeeder={() => setView('trunkfeeder')}
                  onOpenRoutes={(route) => {
                    setHighlightedRoute(route || null);
                    setView('routes');
                  }}
                  onOpenMissed={(route) => {
                    setHighlightedRoute(route);
                    setView('explore');
                  }}
                  onOpenTravel={() => setView('travel')}
                />
              </div>
            </div>
) : view === 'diagnostics' ? (
             <Suspense fallback={<PanelFallback />}>
               <DiagnosticsPanel period={period} />
             </Suspense>
           ) : view === 'equity' ? (
            <Suspense fallback={<PanelFallback />}>
              <EquityPanel />
            </Suspense>
          ) : view === 'brief' ? (
            <div className="flex-1 overflow-y-auto min-w-0">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <ExecutiveBriefPanel
                    serviceDay={settings.serviceDay}
                    onNavigate={(nextView, route) => {
                      setView(nextView as View);
                      if (route) setHighlightedRoute(route);
                    }}
                  />
                </Suspense>
              </div>
            </div>
          ) : view === 'servicequality' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <ServiceQualityPanel />
                </Suspense>
              </div>
            </div>
          ) : view === 'coverage' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <CoveragePanel />
                </Suspense>
              </div>
            </div>
          ) : view === 'changeover' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <ChangeoverPanel />
                </Suspense>
              </div>
            </div>
          ) : view === 'earlydepartures' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <EarlyDeparturesPanel />
                </Suspense>
              </div>
            </div>
          ) : view === 'slowness' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <SlownessCard />
                </Suspense>
              </div>
            </div>
          ) : view === 'scoreboard' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <ForecastScoreboardPanel />
                </Suspense>
              </div>
            </div>
          ) : view === 'measured' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <MeasuredVsModeledPanel />
                </Suspense>
              </div>
            </div>
          ) : view === 'reliability' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-5xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <ReliabilityPanel />
                </Suspense>
              </div>
            </div>
          ) : view === 'tripcheck' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <TripCheckPanel />
                </Suspense>
              </div>
            </div>
          ) : view === 'peers' ? (
            <div className="flex-1 overflow-y-auto">
              <div className="mx-auto max-w-3xl p-2">
                <Suspense fallback={<PanelFallback />}>
                  <PeersPanel />
                </Suspense>
              </div>
            </div>
          ) : (
            <Suspense fallback={<PanelFallback />}>
            <MapWorkspace
              view={view}
              setView={setView}
              circuity={circuity}
              nodes={nodes}
              flaggedRoutes={flaggedRoutes}
              circuityThreshold={circuityThreshold}
              showRoutes={layers.showRoutes}
              showSplits={layers.showSplits}
              showNodes={layers.showNodes}
              showProposedNetwork={layers.showProposedNetwork}
              showOneWay={layers.showOneWay}
              mapEngine={layers.mapEngine}
              setShowRoutes={layers.setShowRoutes}
              setShowSplits={layers.setShowSplits}
              setShowNodes={layers.setShowNodes}
              setShowProposedNetwork={layers.setShowProposedNetwork}
              setShowOneWay={layers.setShowOneWay}
              setMapEngine={layers.setMapEngine}
              corridorSeam={layers.corridorSeam}
              setCorridorSeam={layers.setCorridorSeam}
              highlightedRoute={highlightedRoute}
              setHighlightedRoute={setHighlightedRoute}
              optimizer={{
                ...settings,
                running,
                onRun: runOptimization,
                result,
                onExport: exportGtfs,
                onPlannerReport: downloadPlannerReport,
                downloadPlannerReport,
                resultServiceDay,
                currentPeriodLabel: periodLabel,
                resultPeriodLabel,
              }}
              travelPicks={travel.travelPicks}
              onTravelPicksChange={travel.setTravelPicks}
              serviceDay={settings.serviceDay}
              onTravelItineraries={travel.setTravelItin}
              travelLines={travel.travelLines}
              travelMarkers={travel.travelMarkers}
              onMapPick={travel.onMapPick}
              buildRequest={buildRequest}
            />
            </Suspense>
          )}
          </PanelErrorBoundary>
        </main>
      </div>
    </div>
  );
}
