import { useCallback, useEffect, useRef, useState } from 'react';
import { api } from '../lib/api';
import type {
  OptimizeRequest,
  OptimizeResponse,
  TransferNode,
} from '../types';
import type { ServiceDay } from '../lib/persist';

interface UseOptimizeJobOptions {
  /** Build the request payload from current slider/control values. */
  buildRequest: () => OptimizeRequest;
  period: string;
  serviceDay: ServiceDay;
  /** Called after a successful optimization with the result's nodes. */
  setNodes: React.Dispatch<React.SetStateAction<TransferNode[]>>;
  /** Called with the highlighted route from the result offsets. */
  setHighlightedRoute: (route: string | null) => void;
  /** Called to clear or set global errors. */
  setError: React.Dispatch<React.SetStateAction<string | null>>;
  /** Called with true when a run fails (so Retry can re-run the job),
   * false when a run starts or succeeds. */
  onJobSettled?: (failed: boolean) => void;
}

export function useOptimizeJob({
  buildRequest,
  period,
  serviceDay,
  setNodes,
  setHighlightedRoute,
  setError,
  onJobSettled,
}: UseOptimizeJobOptions) {
  const [running, setRunning] = useState(false);
  const [result, setResult] = useState<OptimizeResponse | null>(null);
  const [resultPeriod, setResultPeriod] = useState<string | null>(null);
  const [resultServiceDay, setResultServiceDay] = useState<ServiceDay | null>(null);

  const jobIdRef = useRef<string | null>(null);
  const pollTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // Synchronous double-submit guard: React 18 batches rapid clicks into one
  // render, so a triple-clicked Run button reaches this hook with `running`
  // still false and would otherwise start 3 concurrent solver jobs (each
  // occupying a backend slot for its full wall-clock budget). The ref is
  // checked+set before the first await, so same-tick re-entries bail out.
  const runInFlightRef = useRef(false);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (pollTimerRef.current) {
        clearInterval(pollTimerRef.current);
        pollTimerRef.current = null;
      }
    };
  }, []);

  const stopPolling = useCallback(() => {
    if (pollTimerRef.current) {
      clearInterval(pollTimerRef.current);
      pollTimerRef.current = null;
    }
  }, []);

  const runOptimization = useCallback(async () => {
    if (runInFlightRef.current) return;
    runInFlightRef.current = true;
    setRunning(true);
    setError(null);
    onJobSettled?.(false);
    stopPolling();

    try {
      const { job_id } = await api.startOptimize(buildRequest());
      jobIdRef.current = job_id;
      pollTimerRef.current = setInterval(async () => {
        try {
          const status = await api.getOptimizeStatus(job_id);
          if (status.status === 'completed' && status.result) {
            setResult(status.result);
            setResultPeriod(period);
            setResultServiceDay(serviceDay);
            setNodes(status.result.nodes.slice(0, 120));
            const moved = status.result.offsets.find(
              (o) => o.movable && o.offset_minutes !== 0
            );
            setHighlightedRoute(moved?.route_short_name ?? null);
            setRunning(false);
            runInFlightRef.current = false;
            onJobSettled?.(false);
            stopPolling();
          } else if (status.status === 'completed') {
            // The backend finished but couldn't produce a result (e.g. its
            // stored outcome failed to re-validate). Stop polling instead of
            // pinging the dead job forever.
            setError(status.error || 'Optimization finished without a usable result');
            setRunning(false);
            runInFlightRef.current = false;
            onJobSettled?.(true);
            stopPolling();
          } else if (status.status === 'failed') {
            setError(status.error || 'Optimization failed');
            setRunning(false);
            runInFlightRef.current = false;
            onJobSettled?.(true);
            stopPolling();
          }
        } catch (e) {
          setError(e instanceof Error ? e.message : String(e));
          setRunning(false);
          runInFlightRef.current = false;
          onJobSettled?.(true);
          stopPolling();
        }
      }, 1500);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setRunning(false);
      runInFlightRef.current = false;
      onJobSettled?.(true);
    }
  }, [buildRequest, period, serviceDay, setNodes, setHighlightedRoute, setError, onJobSettled, stopPolling]);

  const exportGtfs = useCallback(() => {
    // window.open returns null when the browser blocks popups (the default
    // for programmatic opens) — fall back to an anchor download so the
    // button always does something instead of silently failing.
    const url = api.exportStopTimes();
    const win = window.open(url, '_blank');
    if (!win) {
      const a = document.createElement('a');
      a.href = url;
      a.rel = 'noopener';
      document.body.appendChild(a);
      a.click();
      a.remove();
    }
  }, []);

  const downloadPlannerReport = useCallback(() => {
    // Same popup-then-anchor fallback as exportGtfs: the button must always
    // do something instead of silently failing behind a popup blocker.
    const url = api.plannerReport('csv');
    const win = window.open(url, '_blank');
    if (!win) {
      const a = document.createElement('a');
      a.href = url;
      a.rel = 'noopener';
      document.body.appendChild(a);
      a.click();
      a.remove();
    }
  }, []);

  return {
    running,
    result,
    resultPeriod,
    resultServiceDay,
    runOptimization,
    exportGtfs,
    downloadPlannerReport,
  };
}
