import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import './index.css';
import { patchFetchForStatic } from './lib/static-patch';
import App from './App';

patchFetchForStatic();

// Catch runtime errors so the page shows something instead of a blank white screen
window.onerror = (msg, src, line, col, err) => {
  const el = document.getElementById('root');
  if (el) {
    el.innerHTML = `<div style="padding:2rem;color:#f44;font-family:monospace;white-space:pre-wrap">${msg}\n${src}:${line}:${col}\n${err?.stack ?? ''}</div>`;
  }
};
window.addEventListener('unhandledrejection', (e) => {
  const el = document.getElementById('root');
  if (el) {
    el.innerHTML = `<div style="padding:2rem;color:#f44;font-family:monospace;white-space:pre-wrap">Unhandled: ${e.reason}</div>`;
  }
});

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>
);
