import { ChevronDown, ChevronRight } from 'lucide-react';
import { VIEWS, type View } from '../../lib/viewConfig';

export interface AppSidebarProps {
  view: View;
  setView: (v: View) => void;
  collapsed: Record<string, boolean>;
  toggleGroup: (group: string) => void;
}

/** Group the flat VIEWS list into consecutive, order-preserving sections. */
function groupViews(): { group: string; items: typeof VIEWS }[] {
  const groups: { group: string; items: typeof VIEWS }[] = [];
  for (const v of VIEWS) {
    const last = groups[groups.length - 1];
    if (last && last.group === v.group) {
      last.items.push(v);
    } else {
      groups.push({ group: v.group, items: [v] });
    }
  }
  return groups;
}

const GROUPS = groupViews();

/** Dot color encodes the audience: green = measured evidence (network
 * health), blue = modeled proposals (planning sandbox), grey = start-here. */
function groupDotColor(group: string): string {
  if (group.startsWith('Network health')) {
    return 'bg-optimized shadow-[0_0_6px_rgba(0,230,118,0.8)]';
  }
  if (group.startsWith('Planning sandbox')) {
    return 'bg-accent shadow-[0_0_6px_rgba(79,195,247,0.8)]';
  }
  return 'bg-text-muted';
}

/** Badge for views whose evidentiary basis *differs from their group's* —
 * the group header already carries the default ("(measured)" / "(modeled)"),
 * so only exceptions get a chip. A "mixed" chip on a modeled-group view is
 * the honest signal: real data in, model conclusions out. */
function groupDefaultData(group: string): 'measured' | 'modeled' {
  return group.startsWith('Network health') ? 'measured' : 'modeled';
}

/** Tooltip + color per exception. "mixed" = measured input, modeled
 * conclusions — check each number's label. */
const DATA_BADGE: Record<string, { label: string; cls: string }> = {
  measured: { label: 'observed', cls: 'bg-optimized/15 text-optimized' },
  modeled: { label: 'modeled', cls: 'bg-accent/15 text-accent' },
  mixed: { label: 'mixed', cls: 'bg-bottleneck/15 text-bottleneck' },
};

/** Left navigation: grouped, collapsible view switcher. Pure presentation —
 * all state (active view, collapsed groups) is owned by App. */
export default function AppSidebar({ view, setView, collapsed, toggleGroup }: AppSidebarProps) {
  return (
    <nav className="flex w-64 shrink-0 flex-col gap-1 overflow-y-auto border-r border-border bg-card p-2">
      {GROUPS.map(({ group, items }) => {
        const isCollapsed = !!collapsed[group];
        const hasActive = items.some((v) => v.key === view);
        const dotColor = groupDotColor(group);
        return (
          <div key={group}>
            <button
              key={group}
              onClick={() => toggleGroup(group)}
              className="flex w-full items-center gap-1.5 px-2.5 pb-1 pt-2.5 text-[10px] font-bold uppercase tracking-wider text-text-muted hover:text-text-secondary transition-colors"
            >
              <span className={`h-1.5 w-1.5 shrink-0 rounded-full ${dotColor}`} />
              <span className="flex-1 text-left">{group}</span>
              {isCollapsed ? (
                <ChevronRight className="h-3 w-3 shrink-0" />
              ) : (
                <ChevronDown className="h-3 w-3 shrink-0" />
              )}
            </button>
            {!isCollapsed &&
              items.map(({ key, label, desc, Icon, tip, wip, data }) => {
                const active = view === key;
                const measured = key === 'servicequality';
                return (
                  <button
                    key={key}
                    onClick={() => setView(key)}
                    title={tip}
                    className={`flex w-full items-start gap-2.5 rounded-lg px-2.5 py-2 text-left transition-all ${
                      active
                        ? measured
                          ? 'nav-active-measured text-text-primary'
                          : 'nav-active text-text-primary'
                        : 'text-text-secondary hover:bg-card-hover'
                    }`}
                  >
                    <Icon
                      className={`mt-0.5 h-4 w-4 shrink-0 ${
                        active ? (measured ? 'text-optimized' : 'text-accent') : ''
                      }`}
                    />
                    <span className="min-w-0 flex-1">
                      <span className="flex items-center gap-1.5">
                        <span className="block truncate text-xs font-bold">{label}</span>
                        {data && data !== groupDefaultData(group) && DATA_BADGE[data] && (
                          <span
                            title={data === 'measured'
                              ? 'Every number here comes from real vehicle observations'
                              : data === 'modeled'
                                ? 'Numbers here come from schedule-based models — no real-world observations'
                                : 'Combines real observations with modeled estimates — check each number\'s label'}
                            className={`shrink-0 whitespace-nowrap rounded px-1 py-px text-[8px] font-bold uppercase ${DATA_BADGE[data].cls}`}
                          >
                            {DATA_BADGE[data].label}
                          </span>
                        )}
                        {wip && (
                          <span className="shrink-0 whitespace-nowrap rounded bg-amber-500/20 px-1 py-px text-[8px] font-bold uppercase text-amber-400">WIP</span>
                        )}
                      </span>
                      <span className="block text-[10px] leading-snug text-text-muted">{desc}</span>
                    </span>
                  </button>
                );
              })}
            {/* Collapsed but has active child — show compact indicator */}
            {isCollapsed && hasActive && (
              <button
                onClick={() => {
                  toggleGroup(group);
                  // navigate to the active item on expand
                  const activeItem = items.find((v) => v.key === view);
                  if (activeItem) setView(activeItem.key);
                }}
                className="flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-left transition-all nav-active text-text-primary"
              >
                {(() => {
                  const activeItem = items.find((v) => v.key === view);
                  if (!activeItem) return null;
                  const measured = activeItem.key === 'servicequality';
                  return (
                    <>
                      <activeItem.Icon
                        className={`h-4 w-4 shrink-0 ${measured ? 'text-optimized' : 'text-accent'}`}
                      />
                      <span className="text-xs font-bold">{activeItem.label}</span>
                    </>
                  );
                })()}
              </button>
            )}
          </div>
        );
      })}
      <div className="mt-auto flex flex-wrap items-center gap-x-1.5 gap-y-0.5 px-2.5 pb-1 pt-2 text-[9px] leading-tight text-text-muted">
        <span className="rounded bg-bottleneck/15 px-1 py-px font-bold uppercase text-bottleneck">mixed</span>
        <span className="max-w-[15ch]">real observations + modeled conclusions</span>
      </div>
    </nav>
  );
}
